'use client';
import { useState, useRef, useCallback } from 'react';
import type { MediaItem } from '@/lib/projects';
import { GlbViewer } from './GlbViewer';

interface CarouselProps {
  items: MediaItem[];
  projectTitle: string;
}

export function Carousel({ items, projectTitle }: CarouselProps) {
  const [current, setCurrent] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef(0);

  const prev = useCallback(() => {
    setCurrent((c) => (c === 0 ? items.length - 1 : c - 1));
  }, [items.length]);

  const next = useCallback(() => {
    setCurrent((c) => (c === items.length - 1 ? 0 : c + 1));
  }, [items.length]);

  const onMouseDown = (e: React.MouseEvent) => {
    dragStart.current = e.clientX;
    setIsDragging(true);
  };

  const onMouseUp = (e: React.MouseEvent) => {
    if (!isDragging) return;
    const diff = e.clientX - dragStart.current;
    if (diff > 50) prev();
    else if (diff < -50) next();
    setIsDragging(false);
  };

  const item = items[current];

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      {/* Main slide */}
      <div
        style={{
          position: 'relative',
          width: '100%',
          aspectRatio: item.type === 'glb' ? '4/3' : '16/10',
          overflow: 'hidden',
          background: item.type === 'glb' ? 'var(--gray-900)' : 'var(--gray-100)',
          cursor: isDragging ? 'grabbing' : 'grab',
          userSelect: 'none',
        }}
        onMouseDown={onMouseDown}
        onMouseUp={onMouseUp}
        onMouseLeave={() => setIsDragging(false)}
      >
        {item.type === 'image' ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={item.src}
            alt={item.alt}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              display: 'block',
              transition: 'opacity 0.4s ease',
              pointerEvents: 'none',
            }}
            onError={(e) => {
              const el = e.currentTarget as HTMLImageElement;
              el.style.display = 'none';
              const parent = el.parentElement;
              if (parent) {
                parent.style.background = 'var(--gray-100)';
                const placeholder = document.createElement('div');
                placeholder.style.cssText = `
                  position: absolute; inset: 0; display: flex; align-items: center;
                  justify-content: center; flex-direction: column; gap: 0.5rem;
                `;
                placeholder.innerHTML = `
                  <div style="width: 40px; height: 40px; border: 1px solid var(--beige-dark); opacity: 0.4;"></div>
                  <span style="font-family: var(--font-mono); font-size: 0.6rem; letter-spacing: 0.15em; color: var(--gray-500); text-transform: uppercase;">${item.alt}</span>
                `;
                parent.appendChild(placeholder);
              }
            }}
          />
        ) : (
          <GlbViewer src={item.src} height={400} />
        )}

        {/* Slide counter overlay */}
        <div
          style={{
            position: 'absolute',
            bottom: '1rem',
            left: '1.5rem',
            fontFamily: 'var(--font-mono)',
            fontSize: '0.6rem',
            letterSpacing: '0.15em',
            color: item.type === 'glb' ? 'var(--beige)' : 'var(--white)',
            opacity: 0.7,
            pointerEvents: 'none',
          }}
        >
          {String(current + 1).padStart(2, '0')} / {String(items.length).padStart(2, '0')}
        </div>

        {/* Media type label */}
        {item.type === 'glb' && (
          <div
            style={{
              position: 'absolute',
              top: '1rem',
              left: '1.5rem',
              fontFamily: 'var(--font-mono)',
              fontSize: '0.55rem',
              letterSpacing: '0.2em',
              color: 'var(--beige)',
              opacity: 0.6,
              pointerEvents: 'none',
            }}
          >
            3D · INTERACTIVE
          </div>
        )}
      </div>

      {/* Controls */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '1rem 0',
          borderBottom: '1px solid var(--gray-100)',
        }}
      >
        {/* Thumbnail strip */}
        <div
          style={{
            display: 'flex',
            gap: '0.5rem',
            overflow: 'hidden',
            flex: 1,
          }}
        >
          {items.map((it, i) => (
            <button
              key={i}
              onClick={() => setCurrent(i)}
              data-hover
              style={{
                width: 40,
                height: 32,
                border: i === current ? '2px solid var(--black)' : '1px solid var(--gray-300)',
                background: it.type === 'glb' ? 'var(--gray-900)' : 'var(--gray-100)',
                cursor: 'pointer',
                padding: 0,
                overflow: 'hidden',
                flexShrink: 0,
                transition: 'border-color 0.2s ease',
                position: 'relative',
              }}
              title={it.alt}
            >
              {it.type === 'image' ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={it.src}
                  alt=""
                  style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
                />
              ) : (
                <div
                  style={{
                    width: '100%',
                    height: '100%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                  }}
                >
                  <span style={{ fontSize: '8px', color: 'var(--beige)', fontFamily: 'var(--font-mono)' }}>3D</span>
                </div>
              )}
            </button>
          ))}
        </div>

        {/* Arrow controls */}
        <div style={{ display: 'flex', gap: '0.75rem', marginLeft: '1rem' }}>
          <button
            onClick={prev}
            data-hover
            style={{
              width: 36,
              height: 36,
              border: '1px solid var(--gray-300)',
              background: 'transparent',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'border-color 0.2s ease, background 0.2s ease',
            }}
            onMouseEnter={(e) => {
              (e.currentTarget as HTMLButtonElement).style.borderColor = 'var(--black)';
              (e.currentTarget as HTMLButtonElement).style.background = 'var(--black)';
              (e.currentTarget as HTMLButtonElement).querySelector('svg')!.setAttribute('stroke', 'var(--white)');
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.borderColor = 'var(--gray-300)';
              (e.currentTarget as HTMLButtonElement).style.background = 'transparent';
              (e.currentTarget as HTMLButtonElement).querySelector('svg')!.setAttribute('stroke', 'var(--black)');
            }}
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="var(--black)" strokeWidth="1.5">
              <path d="M9 2L4 7l5 5" />
            </svg>
          </button>
          <button
            onClick={next}
            data-hover
            style={{
              width: 36,
              height: 36,
              border: '1px solid var(--gray-300)',
              background: 'transparent',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              transition: 'border-color 0.2s ease, background 0.2s ease',
            }}
            onMouseEnter={(e) => {
              (e.currentTarget as HTMLButtonElement).style.borderColor = 'var(--black)';
              (e.currentTarget as HTMLButtonElement).style.background = 'var(--black)';
              (e.currentTarget as HTMLButtonElement).querySelector('svg')!.setAttribute('stroke', 'var(--white)');
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.borderColor = 'var(--gray-300)';
              (e.currentTarget as HTMLButtonElement).style.background = 'transparent';
              (e.currentTarget as HTMLButtonElement).querySelector('svg')!.setAttribute('stroke', 'var(--black)');
            }}
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none" stroke="var(--black)" strokeWidth="1.5">
              <path d="M5 2l5 5-5 5" />
            </svg>
          </button>
        </div>
      </div>

      {/* Caption */}
      <p
        style={{
          fontFamily: 'var(--font-mono)',
          fontSize: '0.6rem',
          letterSpacing: '0.1em',
          color: 'var(--gray-500)',
          marginTop: '0.5rem',
          textTransform: 'uppercase',
        }}
      >
        {item.alt}
      </p>
    </div>
  );
}
